inputs.fragment_shader:
#version 300 es
precision highp float;
// Těžiště masky postavy (BiRefNet) → výstup 1×1 px: r = x, g = y (souřadnice textury), b = 1 když maska není prázdná
uniform sampler2D u_image0;
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;
void main() {
    const int N = 64;
    vec3 acc = vec3(0.0);
    for (int j = 0; j < N; j++) {
        for (int i = 0; i < N; i++) {
            vec2 uv = (vec2(float(i), float(j)) + 0.5) / float(N);
            float m = texture(u_image0, uv).r;
            acc += vec3(uv * m, m);
        }
    }
    bool ok = acc.z > float(N * N) * 0.005;   // aspoň 0,5 % plochy je postava
    fragColor0 = ok ? vec4(acc.xy / acc.z, 1.0, 1.0) : vec4(0.5, 0.5, 0.0, 1.0);
}

#version 300 es
precision highp float;
// Reflektor C: zvednutí stínů (gamma), S-křivka kolem 0,45, sytost, eliptické světlo na postavu
// s teplým nádechem a ztmavení okrajů. Střed světla = těžiště masky postavy, nebo ruční střed.
uniform sampler2D u_image0;   // obrázek
uniform sampler2D u_image1;   // 1×1 px těžiště masky (r, g; b = platné)
uniform float u_float0;       // gamma (0.80)
uniform float u_float1;       // kontrast (1.18)
uniform float u_float2;       // sytost (1.15)
uniform float u_float3;       // síla reflektoru (0.28)
uniform float u_float4;       // teplo (0.06)
uniform float u_float5;       // ztmavení okrajů, max (0.22)
uniform float u_float6;       // poloosa X (0.42)
uniform float u_float7;       // poloosa Y (0.50)
uniform float u_float8;       // střed X ručně, 0–1 zleva (záporné = podle masky)
uniform float u_float9;       // střed Y ručně, 0–1 shora (záporné = podle masky)
uniform float u_float10;      // posun středu Y od těžiště masky, + = níž (0.0)
in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;
void main() {
    vec3 c = texture(u_image0, v_texCoord).rgb;
    c = pow(max(c, 0.0), vec3(u_float0));
    c = clamp(0.45 + (c - 0.45) * u_float1, 0.0, 1.0);
    float L = dot(c, vec3(0.299, 0.587, 0.114));
    c = L + (c - L) * u_float2;

    vec4 cm = texture(u_image1, vec2(0.5));
    vec2 f = cm.b > 0.5 ? cm.rg : vec2(0.5);
    f.y -= u_float10;                                   // textura má y zdola nahoru
    if (u_float8 >= 0.0) f.x = u_float8;
    if (u_float9 >= 0.0) f.y = 1.0 - u_float9;

    float d = length((v_texCoord - f) / vec2(u_float6, u_float7));
    float k = d < 1.0 ? 1.0 + u_float3 * (1.0 - d * d) : 1.0 - min(u_float5, (d - 1.0) * 0.35);
    c *= k;
    if (d < 1.0) { float w = (1.0 - d) * u_float4; c.r += w; c.g += w * 0.5; }
    fragColor0 = vec4(clamp(c, 0.0, 1.0), 1.0);
}
